/**
 * Component: Scooby’s Hello – A Tailwind CSS Cartoon Animation
 * Author: @bonheur-developer1 (https://tailwindflex.com/@bonheur-developer1)
 * Source: https://tailwindflex.com/@bonheur-developer1/scooby-s-hello-a-tailwind-css-cartoon-animation
 * Attribution: Créé par @bonheur-developer1 sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function ScoobySHelloATailwindCssCartoonAnimation() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en" >
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Scooby Animation Minimal</title>

  <style>
    @keyframes slideIn {
      0% { transform: translateX(-150%); opacity: 0; }
      100% { transform: translateX(0); opacity: 1; }
    }
    @keyframes tailWag {
      0%, 100% { transform: rotate(15deg); }
      50% { transform: rotate(-15deg); }
    }
    @keyframes bubbleFadeIn {
      0% { opacity: 0; transform: translateY(10px); }
      100% { opacity: 1; transform: translateY(0); }
    }
    .slide-in { animation: slideIn 2s ease forwards; opacity: 0; position: relative; }
    .tail-wag { animation: tailWag 0.6s ease-in-out infinite; transform-origin: left center; }
    .bubble-fade-in { animation: bubbleFadeIn 1s ease forwards; animation-delay: 2.2s; opacity: 0; }
    .speech-bubble::after {
      content: "";
      position: absolute;
      left: -10px; top: 50%; transform: translateY(-50%);
      border-width: 10px;
      border-style: solid;
      border-color: transparent #FEF3C7 transparent transparent;
    }
  </style>
</head>
<body class="flex items-left justify-center min-h-screen bg-gradient-to-tr from-indigo-200 via-purple-200 to-pink-200">

  <div class="slide-in flex items-center space-x-4">

    <!-- Dog Body -->
    <div class="relative w-[120px] h-[80px] bg-[#A0522D] rounded-[40px_40px_30px_30px] shadow-lg">

      <!-- Tail -->
      <div class="tail-wag absolute top-8 -right-6 w-[30px] h-[10px] rounded-[20px] bg-[#8B4513]"></div>

      <!-- Head -->
      <div class="absolute top-0 -left-10 w-[70px] h-[70px] bg-[#D2B48C] rounded-full border-4 border-[#8B4513] z-10">

        <!-- Ears -->
        <div class="absolute top-1 -left-4 w-5 h-10 bg-[#8B4513] rounded-md rotate-[-20deg] origin-bottom-left"></div>
        <div class="absolute top-1 left-4 w-5 h-10 bg-[#8B4513] rounded-md rotate-[20deg] origin-bottom-left"></div>

        <!-- Eye -->
        <div class="absolute top-5 left-4 w-3 h-3 bg-white rounded-full border-2 border-black">
          <div class="absolute top-1 left-1 w-1.5 h-1.5 bg-black rounded-full"></div>
        </div>

        <!-- Nose -->
        <div class="absolute top-11 left-6 w-4 h-2.5 bg-black rounded-[40%_40%_60%_60%]"></div>

      </div>

    </div>

    <!-- Speech bubble -->
    <div class="speech-bubble bubble-fade-in relative bg-yellow-100 text-purple-700 font-semibold px-5 py-3 rounded-3xl text-xl select-none"
         style="font-family:'Comic Sans MS', cursive, sans-serif;">
      Hello!
    </div>

  </div>

</body>
</html>" }} />
  );
}
